if($env:USERNAME-ne'KoettLab'-or$env:COMPUTERNAME-ne'KOETT-LAB'){throw 'These checks run only in the isolated Koett Windows lab guest'}
$null=Run-MediaCli 'recovery';Start-Process narrator.exe;Start-Sleep -Milliseconds 1500;$h=[LabDriver]::ByClass('KoettRecoveryWindow');Activate-LabEditor $h;$w=[Windows.Automation.AutomationElement]::FromHandle($h)
$fields=@($w.FindAll([Windows.Automation.TreeScope]::Descendants,[Windows.Automation.Condition]::TrueCondition)|Where-Object {$_.Current.AutomationId-in@('1','3','2')}|ForEach-Object {@{id=$_.Current.AutomationId;name=$_.Current.Name;type=$_.Current.ControlType.ProgrammaticName;enabled=$_.Current.IsEnabled}})
$e=$w.FindFirst([Windows.Automation.TreeScope]::Descendants,(New-Object Windows.Automation.PropertyCondition([Windows.Automation.AutomationElement]::AutomationIdProperty,'102')));$e.SetFocus();$watch=[Diagnostics.Stopwatch]::StartNew();do{Start-Sleep -Milliseconds 100;$id=[Windows.Automation.AutomationElement]::FocusedElement.Current.AutomationId}while($id-ne'102'-and$watch.ElapsedMilliseconds-lt3000);if($id-ne'102'){throw 'Editor focus did not settle'};[Windows.Forms.SendKeys]::SendWait('{TAB}');$watch=[Diagnostics.Stopwatch]::StartNew();do{Start-Sleep -Milliseconds 100;$id=[Windows.Automation.AutomationElement]::FocusedElement.Current.AutomationId}while($id-ne'2'-and$watch.ElapsedMilliseconds-lt3000);$focused=[Windows.Automation.AutomationElement]::FocusedElement.Current.Name;$step=Get-LabWindowStep 'narrator-recovery-close-keyboard' $h;[Windows.Forms.SendKeys]::SendWait('{ENTER}');$watch=[Diagnostics.Stopwatch]::StartNew();do{Start-Sleep -Milliseconds 100;$closed=[LabDriver]::ByClass('KoettRecoveryWindow')-eq[IntPtr]::Zero}while(-not$closed-and$watch.ElapsedMilliseconds-lt3000)
@{passed=($focused-eq'Close'-and[LabDriver]::ByClass('KoettRecoveryWindow')-eq[IntPtr]::Zero-and@($fields|Where-Object {$_.name-in@('Copy unsaved','Retry save','Close')}).Count-eq3);narrator=@(Get-Process Narrator -ErrorAction SilentlyContinue|Select-Object Id,ProcessName);fields=$fields;focus_name=$focused;step=$step;status=Run-MediaCli 'status';artifact=Get-LabArtifact}
